import urllib.request
import urllib.error
import time
from typing import Optional

class RateLimitError(Exception):
    """Raised when the API returns a 429 Too Many Requests error after retries."""
    pass

class ServerError(Exception):
    """Raised when the API returns a 5xx error after retries."""
    pass

class ClientError(Exception):
    """Raised when the API returns a 4xx error (excluding 429)."""
    pass

class ConnectionError(Exception):
    """Raised when a network error occurs after retries."""
    pass

class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def _make_request(self, path: str) -> str:
        url = f"{self.base_url}{path}"
        max_retries = 3
        backoff_times = [0.5, 1.0, 2.0]

        for attempt in range(max_retries):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                status_code = e.code
                if status_code == 429:
                    if attempt < len(backoff_times):
                        time.sleep(backoff_times[attempt])
                        continue
                    raise RateLimitError(f"Rate limit exceeded after retries for {url}")
                elif 500 <= status_code < 600:
                    if attempt == 0:
                        time.sleep(1.0)
                        continue
                    raise ServerError(f"Server error {status_code} for {url}")
                else:
                    raise ClientError(f"Client error {status_code} for {url}")
            except urllib.error.URLError as e:
                if attempt == 0:
                    time.sleep(1.0)
                    continue
                raise ConnectionError(f"Network error for {url}: {e.reason}")

        # This part should theoretically not be reached due to retry logic above
        if status_code == 429:
            raise RateLimitError(f"Rate limit exceeded after retries for {url}")
        elif 500 <= status_code < 600:
            raise ServerError(f"Server error {status_code} for {url}")
        else:
            raise ClientError(f"Client error {status_code} for {url}")

    def get(self, path: str) -> str:
        return self._make_request(path)
